    // Напишите решение здесь.
    return 0;
}

exercise.referenceSolution:
#include <iostream>
#include <optional>
#include <print>
#include <string>
#include <vector>

class BoundedStack {
public:
    explicit BoundedStack(std::size_t capacity) : capacity_(capacity) {}

    bool push(int x) {
        if (items_.size() == capacity_) {
            return false;
        }
        items_.push_back(x);
        return true;
    }

    std::optional<int> pop() {
        if (items_.empty()) {
            return std::nullopt;
        }
        const int x = items_.back();
        items_.pop_back();
        return x;
    }

    std::optional<int> top() const {
        if (items_.empty()) {
            return std::nullopt;
        }
        return items_.back();
    }

    std::size_t size() const {
        return items_.size();
    }

private:
    std::size_t capacity_;
    std::vector<int> items_;
};

void print(std::optional<int> value) {
    if (value) {
        std::println("{}", *value);
    } else {
        std::println("пусто");
    }
}

int main() {
    std::size_t capacity;
    std::cin >> capacity;
    BoundedStack stack(capacity);
    std::string command;
    while (std::cin >> command) {
        if (command == "push") {
            int x;
            std::cin >> x;
            if (!stack.push(x)) {
                std::println("переполнение");
            }
        } else if (command == "pop") {
            print(stack.pop());
        } else if (command == "top") {
            print(stack.top());
        } else {
            std::println("{}", stack.size());
        }
    }
    return 0;
}

additionalExercises.description:
Класс `Pipeline` хранит шаги обработки `std::vector<std::function<long long(long long)>>` и применяет их по порядку в `long long run(long long x) const`. Команды:

- `add k` — шаг «x + k»;
- `mul k` — шаг «x · k»;
- `clamp lo hi` — шаг «ограничить отрезком [lo, hi]»;
- `abs` — шаг «модуль»;
- `reset` — удалить все шаги;
- `run x` — напечатать `x → результат`.

Шаги добавляются к концу конвейера и действуют на все последующие `run`.

