#include <algorithm>
#include <functional>
#include <iostream>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Pipeline {
public:
    Pipeline &then(std::function<long long(long long)> step) {
        steps_.push_back(std::move(step));
        return *this;
    }

    void reset() {
        steps_.clear();
    }

    long long run(long long x) const {
        for (const auto &step : steps_) {
            x = step(x);
        }
        return x;
    }

private:
    std::vector<std::function<long long(long long)>> steps_;
};

int main() {
    Pipeline pipeline;
    std::string command;
    while (std::cin >> command) {
        if (command == "add") {
            long long k;
            std::cin >> k;
            pipeline.then([k](long long x) { return x + k; });
        } else if (command == "mul") {
            long long k;
            std::cin >> k;
            pipeline.then([k](long long x) { return x * k; });
        } else if (command == "clamp") {
            long long lo, hi;
            std::cin >> lo >> hi;
            pipeline.then([lo, hi](long long x) { return std::clamp(x, lo, hi); });
        } else if (command == "abs") {
            pipeline.then([](long long x) { return x < 0 ? -x : x; });
        } else if (command == "reset") {
            pipeline.reset();
        } else {
            long long x;
            std::cin >> x;
            std::println("{} → {}", x, pipeline.run(x));
        }
    }
    return 0;
}

