#include <algorithm>
#include <iostream>
#include <print>
#include <string>
#include <vector>

class SortedList : public std::vector<int> {
public:
    void add(int x) {
        insert(std::ranges::upper_bound(*this, x), x);
    }

    bool contains(int x) const {
        return std::ranges::binary_search(*this, x);
    }
};

int main() {
    SortedList list;
    std::string command;
    while (std::cin >> command) {
        if (command == "add") {
            int x;
            std::cin >> x;
            list.add(x);
        } else if (command == "bulk") {
            int n;
            std::cin >> n;
            for (int i = 0; i < n; ++i) {
                int x;
                std::cin >> x;
                list.push_back(x);  // быстрее, чем add
            }
        } else if (command == "has") {
            int x;
            std::cin >> x;
            std::println("{}", list.contains(x) ? "да" : "нет");
        } else {
            std::string line;
            for (int x : list) {
                line += (line.empty() ? "" : " ") + std::to_string(x);
            }
            std::println("{}", line.empty() ? "пусто" : line);
        }
    }
    return 0;
}

