int main() {
    std::vector<std::function<int(int)>> steps{[](int x) { return x * 3; }, [](int x) { return x - 1; }};
    int a = 2, b = 2;
    for (const auto &s : steps) {
        a = s(a);
    }
    for (auto it = steps.rbegin(); it != steps.rend(); ++it) {
        b = (*it)(b);
    }
    std::println("{} {}", a, b);
